with kept_keys as (select status, order_id from payments except select status, order_id from payments where status not in ('FAILED', 'SUCCESS')), verified as (select s.* from payments s join kept_keys k on s.status = k.status and s.order_id = k.order_id) select id, order_id, amount, paid_at, status, case when status rlike '^(FAILED|REFUNDED)$' then 'CORE' else 'EXTENDED' end as status_zone from verified order by paid_at desc, status;
